The fit is separated from the measurement so the statistics can be tested deterministically with synthetic power laws, while one real-timing test checks the integration with a wide margin. Taking the best of several repeats follows the `timeit` guidance that noise only adds time.

**`growth.py`**

```python
from __future__ import annotations

import math
import timeit
from collections.abc import Callable, Sequence
from typing import Any, TypeVar

T = TypeVar("T")


def measure(
    func: Callable[[T], Any],
    make_input: Callable[[int], T],
    sizes: Sequence[int],
    *,
    repeat: int = 3,
    number: int = 1,
) -> list[float]:
    """Best-of-`repeat` seconds per call of func(make_input(n)) for each n in sizes."""
    results: list[float] = []
    for n in sizes:
        data = make_input(n)  # input construction is not timed
        best = min(timeit.repeat(lambda: func(data), repeat=repeat, number=number))
        results.append(best / number)
    return results


def growth_exponent(sizes: Sequence[int], times: Sequence[float]) -> float:
    """Least-squares slope of log(time) against log(n)."""
    if len(sizes) != len(times) or len(sizes) < 2:
        raise ValueError("need at least two (size, time) pairs of equal length")
    if any(n <= 0 for n in sizes) or any(t <= 0 for t in times):
        raise ValueError("sizes and times must be positive")
    xs = [math.log(n) for n in sizes]
    ys = [math.log(t) for t in times]
    mean_x = sum(xs) / len(xs)
    mean_y = sum(ys) / len(ys)
    var_x = sum((x - mean_x) ** 2 for x in xs)
    if var_x == 0:
        raise ValueError("sizes must not all be equal")
    cov = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
    return cov / var_x


def classify(exponent: float) -> str:
    if exponent < 0.4:
        return "O(1)-ish"
    if exponent < 1.35:
        return "O(n)-ish"
    if exponent < 2.5:
        return "O(n^2)-ish"
    return "worse than quadratic"


def analyse(
    func: Callable[[T], Any],
    make_input: Callable[[int], T],
    sizes: Sequence[int],
    **kwargs: Any,
) -> tuple[float, str]:
    times = measure(func, make_input, sizes, **kwargs)
    exponent = growth_exponent(sizes, times)
    return exponent, classify(exponent)
```

**`test_growth.py`**

```python
import pytest

from growth import analyse, classify, growth_exponent, measure


def test_exponent_of_exact_power_laws() -> None:
    sizes = [1000, 2000, 4000, 8000]
    assert growth_exponent(sizes, [n * 1e-6 for n in sizes]) == pytest.approx(1.0)
    assert growth_exponent(sizes, [n * n * 1e-9 for n in sizes]) == pytest.approx(2.0)
    assert growth_exponent(sizes, [5e-6 for _ in sizes]) == pytest.approx(0.0, abs=1e-9)


@pytest.mark.parametrize(
    "exponent, label",
    [(0.0, "O(1)-ish"), (1.0, "O(n)-ish"), (1.1, "O(n)-ish"), (2.0, "O(n^2)-ish"), (3.0, "worse than quadratic")],
)
def test_classify(exponent: float, label: str) -> None:
    assert classify(exponent) == label


@pytest.mark.parametrize(
    "sizes, times",
    [([1], [1.0]), ([1, 2], [1.0]), ([1, 1], [1.0, 2.0]), ([0, 2], [1.0, 2.0]), ([1, 2], [0.0, 1.0])],
)
def test_invalid_measurements_raise(sizes, times) -> None:
    with pytest.raises(ValueError):
        growth_exponent(sizes, times)


def test_measure_returns_one_positive_time_per_size() -> None:
    times = measure(lambda xs: sum(xs), lambda n: list(range(n)), [100, 200, 400], repeat=2)
    assert len(times) == 3 and all(t > 0 for t in times)


def dedupe_slow(xs):
    out = []
    for x in xs:
        if x not in out:
            out.append(x)
    return out


def dedupe_fast(xs):
    return list(dict.fromkeys(xs))


def test_slow_dedupe_scales_worse_than_fast_dedupe() -> None:
    make = lambda n: list(range(n))  # all unique: worst case for the list scan
    sizes = [1000, 2000, 4000]
    slow, _ = analyse(dedupe_slow, make, sizes, repeat=3)
    fast, _ = analyse(dedupe_fast, make, sizes, repeat=3)
    assert slow > fast + 0.5
    assert slow > 1.5
```

Run the tests with `pytest -q`.

